exports = module.exports = Version;

var label = process.env.GT_LABEL ? "[" + process.env.GT_LABEL + "]" : "";

function Version(raw) {
  this.raw = raw;
  this.parts = raw.split(".");
}
Version.prototype.major = function () {
  return Number(this.parts[0]);
};
Version.prototype.toString = function () {
  return label + this.raw;
};

exports.MAX_LENGTH = 256;
exports.parse = function parse(raw) {
  return raw.length > exports.MAX_LENGTH ? null : new Version(raw);
};
exports.compare = function compare(a, b) {
  return exports.parse(a).major() - exports.parse(b).major();
};
module.exports.gt = function gt(a, b) {
  return exports.compare(a, b) > 0;
};
